<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { supabase } from '@/lib/supabase'
const router = useRouter()
const products=ref<any[]>([]),customers=ref<any[]>([]),cart=ref<{product_id:number;name:string;quantity:number;price_sell:number;stock:number;track_inventory:boolean}[]>([])
const customer=ref<number|null>(null),showCustomer=ref(false),newCustomerName=ref(''),newCustomerPhone=ref(''),payment=ref('cash'),tax=ref(0),notes=ref(''),search=ref(''),busy=ref(false),error=ref(''),success=ref('')
const subtotal=computed(()=>cart.value.reduce((s,x)=>s+x.quantity*x.price_sell,0)),taxAmount=computed(()=>subtotal.value*Number(tax.value||0)/100),total=computed(()=>subtotal.value+taxAmount.value)
async function load(){const [p,c]=await Promise.all([supabase.from('products').select('id,sku,name,price_sell,stock,track_inventory').order('name'),supabase.from('customers').select('id,name,phone').order('name')]);if(p.error)error.value=p.error.message;else products.value=(p.data??[]).filter(x=>!x.track_inventory||x.stock>0);if(c.error)error.value=c.error.message;else customers.value=c.data??[]}
const matches=computed(()=>products.value.filter(p=>(p.name+' '+p.sku).toLowerCase().includes(search.value.toLowerCase())))
function add(p:any){const item=cart.value.find(x=>x.product_id===p.id);if(item){if(!p.track_inventory||item.quantity<p.stock)item.quantity++}else cart.value.push({product_id:p.id,name:p.name,quantity:1,price_sell:Number(p.price_sell),stock:p.stock,track_inventory:p.track_inventory})}
async function createCustomer(){const name=newCustomerName.value.trim();if(!name)return;const {data,error:e}=await supabase.from('customers').insert({name,phone:newCustomerPhone.value||null}).select('id,name,phone').single();if(e){error.value=e.message;return}customers.value=[...customers.value,data];customer.value=data.id;newCustomerName.value='';newCustomerPhone.value='';showCustomer.value=false}
async function checkout(){if(!cart.value.length)return;busy.value=true;error.value='';success.value='';try{const {data,error:e}=await supabase.rpc('create_sale',{p_customer_id:customer.value,p_payment_method:payment.value,p_tax_rate:Number(tax.value||0),p_notes:notes.value||null,p_items:cart.value.map(x=>({product_id:x.product_id,quantity:x.quantity,price_sell:x.price_sell}))});if(e)throw e;cart.value=[];notes.value='';await router.push(`/receipts/${data}`)}catch(e:any){error.value=e.message??'Could not complete sale'}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>New sale</h1><p>Build a cart, select payment and complete a stock-controlled sale.</p></div></div><p v-if="error" class="alert">{{error}}</p><p v-if="success" class="success">{{success}}</p><div class="sales-grid"><div class="panel"><h2>Products</h2><input v-model="search" class="control" placeholder="Search product or SKU"><div class="product-pick"><button v-for="p in matches" :key="p.id" class="product-option" @click="add(p)"><b>{{p.name}}</b><span>{{p.sku}} · UGX {{Number(p.price_sell).toLocaleString()}}</span><small>{{p.track_inventory?p.stock+' in stock':'Service · stock not tracked'}}</small></button></div></div><div class="panel"><h2>Sale cart</h2><div v-if="!cart.length" class="empty">No items added yet.</div><div v-for="item in cart" :key="item.product_id" class="cart-line"><div><b>{{item.name}}</b><small>UGX {{item.price_sell.toLocaleString()}} each</small></div><input v-model.number="item.quantity" type="number" min="1" :max="item.track_inventory?item.stock:undefined" class="control qty"><input v-model.number="item.price_sell" type="number" min="0" step="0.01" class="control qty" title="Actual selling price"><b>UGX {{(item.quantity*item.price_sell).toLocaleString()}}</b><button class="link danger" @click="cart=cart.filter(x=>x.product_id!==item.product_id)">×</button></div><label>Customer<select v-model="customer" class="control"><option :value="null">Walk-in customer</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}} {{c.phone?'· '+c.phone:''}}</option></select><button type="button" class="link" @click="showCustomer=true">＋ Add new customer</button></label><label>Payment method<select v-model="payment" class="control"><option value="cash">Cash</option><option value="credit">Credit</option></select></label><label>Tax rate (%)<input v-model.number="tax" type="number" min="0" max="100" class="control"></label><label>Notes<textarea v-model="notes" class="control" rows="2"/></label><div class="totals"><div>Subtotal <b>UGX {{subtotal.toLocaleString()}}</b></div><div>Tax <b>UGX {{taxAmount.toLocaleString()}}</b></div><div class="grand">Total <b>UGX {{total.toLocaleString()}}</b></div></div><button class="btn primary full" :disabled="busy||!cart.length||cart.some(x=>x.quantity<1||(x.track_inventory&&x.quantity>x.stock)||x.price_sell<0)|| (payment==='credit'&&!customer)" @click="checkout">{{busy?'Processing…':'Complete sale'}}</button></div></div><div v-if="showCustomer" class="modal-backdrop" @click.self="showCustomer=false"><form class="modal" @submit.prevent="createCustomer"><h2>New customer</h2><label>Name<input v-model="newCustomerName" class="control" required></label><label>Phone<input v-model="newCustomerPhone" class="control"></label><div class="modal-actions"><button type="button" class="btn" @click="showCustomer=false">Cancel</button><button class="btn primary">Save customer</button></div></form></div></section></template>
